<?php require __DIR__.'/../partials/dashboard-head.php'; ?>
<div class="dash-head"><h1>Yêu cầu mua hàng</h1><p style="color:#667085">Đề xuất mua, phê duyệt và tạo đơn mua từ sản phẩm chạm tồn tối thiểu.</p></div>
<?php foreach(getFlash() as $x): ?><div class="alert alert-<?= e($x['type']) ?>"><?= e($x['message']) ?></div><?php endforeach; ?>
<?php if($canCreate): ?><div class="panel" style="padding:16px;margin-bottom:16px"><form method="post" action="/admin/purchase-requests"><?= csrfField() ?><div style="display:flex;gap:12px;align-items:end;flex-wrap:wrap"><div class="form-group" style="min-width:280px"><label>Nhà cung cấp *</label><select name="supplier_id" required><option value="">Chọn nhà cung cấp</option><?php foreach($suppliers as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></div><div class="form-group" style="flex:1;min-width:280px"><label>Ghi chú</label><input name="note" maxlength="500"></div><button class="btn btn-navy">Tạo yêu cầu mua</button></div><div style="overflow:auto;margin-top:14px"><table class="tbl"><thead><tr><th>Sản phẩm</th><th>Tồn</th><th>Tối thiểu</th><th>Đề nghị mua</th></tr></thead><tbody><?php foreach($low as $p): ?><tr><td><strong><?= e($p['name']) ?></strong><div class="fs-11 text-muted"><?= e($p['sku']) ?> <?= e($p['oem_code']) ?></div></td><td><?= (int)$p['stock'] ?></td><td><?= (int)$p['min_stock'] ?></td><td><input name="qty[<?= (int)$p['id'] ?>]" inputmode="numeric" value="<?= max(1,(int)$p['max_stock']-(int)$p['stock']) ?>" style="width:110px"></td></tr><?php endforeach; ?><?php if(!$low): ?><tr><td colspan="4" style="padding:24px;text-align:center">Không có sản phẩm chạm tồn tối thiểu.</td></tr><?php endif; ?></tbody></table></div></form></div><?php endif; ?>
<div class="panel"><div style="overflow:auto"><table class="tbl"><thead><tr><th>Mã</th><th>Nhà cung cấp</th><th>Người lập</th><th>Mặt hàng</th><th>Trạng thái</th><th>PO</th><th>Duyệt PO</th><th>Thao tác YC</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><strong><?= e($i['code']) ?></strong><div class="fs-11 text-muted"><?= e($i['created_at']) ?></div></td><td><?= e($i['supplier_name']) ?></td><td><?= e($i['creator_name'] ?: '-') ?></td><td><?= (int)$i['item_count'] ?></td><td><strong><?= $i['status']==='approved'?'Đã duyệt':($i['status']==='rejected'?'Từ chối':'Chờ duyệt') ?></strong><?php if($i['rejection_reason']): ?><div class="fs-11 text-muted"><?= e($i['rejection_reason']) ?></div><?php endif; ?></td><td><?= e($i['po_code'] ?: '-') ?><?php if($i['po_code']): ?><div class="fs-11 text-muted"><?= $i['po_status']==='approved'?'Đã duyệt':($i['po_status']==='rejected'?'Từ chối':'Nháp') ?></div><?php if($i['po_rejection_reason']): ?><div class="fs-11 text-muted"><?= e($i['po_rejection_reason']) ?></div><?php endif; ?><?php endif; ?></td><td><?php if($i['po_id']&&$i['po_status']==='draft'&&$canApproveOrder&&(int)$i['po_created_by']!==$currentUserId): ?><form method="post" action="/admin/purchase-orders/<?= (int)$i['po_id'] ?>/approve" style="display:flex;gap:5px;min-width:300px"><?= csrfField() ?><input name="po_rejection_reason" maxlength="300" placeholder="Lý do nếu từ chối"><button class="btn btn-sm btn-navy">Duyệt PO</button><button class="btn btn-sm btn-outline-navy" formaction="/admin/purchase-orders/<?= (int)$i['po_id'] ?>/reject">Từ chối</button></form><?php elseif($i['po_id']&&$i['po_status']==='draft'&&(int)$i['po_created_by']===$currentUserId): ?><span class="fs-11 text-muted">Không thể tự duyệt PO</span><?php else: ?>-<?php endif; ?></td><td><?php if($i['status']==='pending'&&$canApprove&&(int)$i['created_by']!==$currentUserId): ?><form method="post" action="/admin/purchase-requests/<?= (int)$i['id'] ?>/approve" style="display:flex;gap:5px;min-width:300px"><?= csrfField() ?><input name="reason" maxlength="300" placeholder="Lý do nếu từ chối"><button class="btn btn-sm btn-navy">Duyệt</button><button class="btn btn-sm btn-outline-navy" formaction="/admin/purchase-requests/<?= (int)$i['id'] ?>/reject">Từ chối</button></form><?php elseif($i['status']==='pending'&&(int)$i['created_by']===$currentUserId): ?><span class="fs-11 text-muted">Không thể tự duyệt</span><?php elseif($i['status']==='approved'&&$canCreateOrder&&!$i['po_code']): ?><form method="post" action="/admin/purchase-requests/<?= (int)$i['id'] ?>/purchase-order"><?= csrfField() ?><button class="btn btn-sm btn-navy">Tạo PO</button></form><?php else: ?>-<?php endif; ?></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="8" style="padding:25px;text-align:center">Chưa có yêu cầu mua.</td></tr><?php endif; ?></tbody></table></div></div>
